using GH_Net.Repository.Entities;using Microsoft.EntityFrameworkCore;
namespace GH_Net.Repository.Data;
public class PrinterManagerDbContext(DbContextOptions<PrinterManagerDbContext> options):DbContext(options)
{public DbSet<Job> Jobs=>Set<Job>();public DbSet<PrinterConfig> PrinterConfigs=>Set<PrinterConfig>();public DbSet<Product> Products=>Set<Product>();public DbSet<Carton> Cartons=>Set<Carton>();public DbSet<Pallet> Pallets=>Set<Pallet>();public DbSet<ScanEvent> ScanEvents=>Set<ScanEvent>();public DbSet<PrintAttempt> PrintAttempts=>Set<PrintAttempt>();public DbSet<ScannerConfig> ScannerConfigs=>Set<ScannerConfig>();public static PrinterManagerDbContext Create(string connectionString)=>new(new DbContextOptionsBuilder<PrinterManagerDbContext>().UseSqlite(connectionString).Options);public static string DefaultConnectionString=>"Data Source="+Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ghnet_cj.db")+";Default Timeout=5;Pooling=True";
protected override void OnModelCreating(ModelBuilder m){m.Entity<Job>(e=>{e.ToTable("Jobs",t=>t.HasCheckConstraint("CK_Jobs_Capacity","ProductsPerCarton > 0 AND CartonsPerPallet > 0"));e.HasKey(x=>x.Id);e.Property(x=>x.Name).IsRequired().HasMaxLength(200);e.Property(x=>x.Status).HasConversion<int>();e.Property(x=>x.PackingWorkflowState).HasConversion<int>();foreach(var n in new[]{nameof(Job.ProductCsvFileName),nameof(Job.CartonCsvFileName),nameof(Job.PalletCsvFileName)})e.Property(n).HasMaxLength(260);foreach(var n in new[]{nameof(Job.ProductCodeColumn),nameof(Job.CartonCodeColumn),nameof(Job.PalletCodeColumn)})e.Property(n).HasMaxLength(200);e.HasIndex(x=>x.Status);e.HasIndex(x=>x.CreatedAt);});
m.Entity<PrinterConfig>(e=>{e.ToTable("PrinterConfigs");e.HasKey(x=>x.Id);e.Property(x=>x.Ip).IsRequired().HasMaxLength(45);});
m.Entity<Product>(e=>{e.ToTable("Products",t=>t.HasCheckConstraint("CK_Products_Row","SourceRowIndex >= 0"));e.HasKey(x=>x.Id);e.Property(x=>x.Code).IsRequired().HasMaxLength(500);e.Property(x=>x.Status).HasConversion<int>();e.HasOne(x=>x.Job).WithMany(x=>x.Products).HasForeignKey(x=>x.JobId).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Carton).WithMany(x=>x.Products).HasForeignKey(x=>x.CartonId).OnDelete(DeleteBehavior.Restrict);e.HasIndex(x=>new{x.JobId,x.Code}).IsUnique();e.HasIndex(x=>new{x.JobId,x.Status});e.HasIndex(x=>x.CartonId);});
m.Entity<Carton>(e=>{e.ToTable("Cartons",t=>{t.HasCheckConstraint("CK_Cartons_Row","SourceRowIndex >= 0");t.HasCheckConstraint("CK_Cartons_Counts","ProductCount >= 0 AND PrintCount >= 0");});e.HasKey(x=>x.Id);e.Property(x=>x.Code).IsRequired().HasMaxLength(500);e.Property(x=>x.Status).HasConversion<int>();e.HasOne(x=>x.Job).WithMany(x=>x.Cartons).HasForeignKey(x=>x.JobId).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Pallet).WithMany(x=>x.Cartons).HasForeignKey(x=>x.PalletId).OnDelete(DeleteBehavior.Restrict);e.HasIndex(x=>new{x.JobId,x.Code}).IsUnique();e.HasIndex(x=>new{x.JobId,x.SourceRowIndex}).IsUnique();e.HasIndex(x=>new{x.JobId,x.Status});e.HasIndex(x=>x.PalletId);});
m.Entity<Pallet>(e=>{e.ToTable("Pallets",t=>{t.HasCheckConstraint("CK_Pallets_Row","SourceRowIndex >= 0");t.HasCheckConstraint("CK_Pallets_Counts","CartonCount >= 0 AND PrintCount >= 0");});e.HasKey(x=>x.Id);e.Property(x=>x.Code).IsRequired().HasMaxLength(500);e.Property(x=>x.Status).HasConversion<int>();e.HasOne(x=>x.Job).WithMany(x=>x.Pallets).HasForeignKey(x=>x.JobId).OnDelete(DeleteBehavior.Cascade);e.HasIndex(x=>new{x.JobId,x.Code}).IsUnique();e.HasIndex(x=>new{x.JobId,x.SourceRowIndex}).IsUnique();e.HasIndex(x=>new{x.JobId,x.Status});});
m.Entity<ScanEvent>(e=>{e.ToTable("ScanEvents");e.HasKey(x=>x.Id);e.Property(x=>x.ScannedCode).IsRequired().HasMaxLength(500);e.Property(x=>x.ExpectedCodeType).HasConversion<int>();e.Property(x=>x.ResultCode).HasConversion<int>();e.HasOne(x=>x.Job).WithMany().HasForeignKey(x=>x.JobId).OnDelete(DeleteBehavior.Cascade);e.HasIndex(x=>new{x.JobId,x.CreatedAt});});
m.Entity<PrintAttempt>(e=>{e.ToTable("PrintAttempts",t=>{t.HasCheckConstraint("CK_PrintAttempts_Target","(CartonId IS NOT NULL AND PalletId IS NULL) OR (CartonId IS NULL AND PalletId IS NOT NULL)");t.HasCheckConstraint("CK_PrintAttempts_Number","AttemptNumber > 0");});e.HasKey(x=>x.Id);e.Property(x=>x.ZplSnapshot).IsRequired();e.HasOne(x=>x.Job).WithMany().HasForeignKey(x=>x.JobId).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Carton).WithMany().HasForeignKey(x=>x.CartonId).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.Pallet).WithMany().HasForeignKey(x=>x.PalletId).OnDelete(DeleteBehavior.Restrict);e.HasIndex(x=>new{x.JobId,x.CreatedAt});e.HasIndex(x=>x.CartonId);e.HasIndex(x=>x.PalletId);});
m.Entity<ScannerConfig>(e=>{e.ToTable("ScannerConfigs",t=>{t.HasCheckConstraint("CK_Scanner_Baud","BaudRate > 0");t.HasCheckConstraint("CK_Scanner_DataBits","DataBits >= 5 AND DataBits <= 8");t.HasCheckConstraint("CK_Scanner_Timeout","ReadTimeoutMs > 0");});e.HasKey(x=>x.Id);e.Property(x=>x.PortName).IsRequired().HasMaxLength(50);e.Property(x=>x.MessageTerminator).IsRequired().HasMaxLength(10);});}}
